INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophical concepts","Use Ethik vocabulary","Engage with moral questions in German"],"explanation":{"intro":"Philosophy vocabulary at B1 allows engaging with ethical questions and abstract concepts.","culturalNote":"Philosophy has a strong tradition in Germany — Kant, Hegel, Nietzsche, Schopenhauer, Leibniz, Marx are all German. Philosophy (Philosophie) is taught in many German secondary schools. The concept of Weltanschauung (worldview) is distinctly German."},"examples":[{"german":"Kants kategorischer Imperativ besagt, dass man nur so handeln soll, wie man möchte, dass alle handeln.","english":"Kant''s categorical imperative states that one should act only as one would wish everyone to act."},{"german":"Die Frage nach dem Sinn des Lebens beschäftigt die Philosophie seit Jahrtausenden.","english":"The question of the meaning of life has occupied philosophy for millennia."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can engage with philosophical concepts and ethical questions in German."}}',
'{"items":[{"word":"der kategorische Imperativ","translation":"categorical imperative","pronunciation":"dayr kat-eh-GOH-rish-eh im-peh-rah-TEEF","example":"Kants Imperativ."},{"word":"der Sinn des Lebens","translation":"meaning of life","pronunciation":"dayr ZIN des LAY-bens","example":"Der Sinn des Lebens."},{"word":"die Ethik","translation":"ethics","pronunciation":"dee EY-tik","example":"Moralische Ethik."},{"word":"die Weltanschauung","translation":"worldview","pronunciation":"dee VELT-an-show-oong","example":"Eine Weltanschauung."},{"word":"besagen","translation":"to state/say/mean","pronunciation":"beh-ZAH-gen","example":"Das besagt."},{"word":"jahrtausendelang","translation":"for millennia","pronunciation":"YAHR-tow-zen-deh-lang","example":"Jahrtausende lang."}]}',
'{"title":"Besagen — to state/mean (formal)","pattern":"etwas besagt, dass + verb-final clause (something states/says that)","explanation":"Besagen (to state, say, mean — for texts, laws, rules): Das Gesetz besagt, dass... = The law states that... Der Text besagt Folgendes = The text states the following. Formal written verb — not for persons. Past: besagte. Related: aussagen (to state, testify), aussagen über (to say about). Note: nicht viel besagen = not to mean much: Das besagt nicht viel.","examples":[{"sentence":"Die Studie besagt, dass Kaffee gesund sein kann.","translation":"The study states that coffee can be healthy."},{"sentence":"Das Grundgesetz besagt, dass alle Menschen gleich sind.","translation":"The Basic Law states that all people are equal."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Weltanschauung'' means?","options":["worldview","philosophy","ideology","belief system"],"correctAnswer":"worldview"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The question of the meaning of life has occupied philosophy for millennia.","options":["Die Frage nach dem Sinn des Lebens beschäftigt die Philosophie seit Jahrtausenden.","Philosophen fragen nach dem Sinn.","Der Sinn des Lebens ist philosophisch.","Die Philosophie ist alt."],"correctAnswer":"Die Frage nach dem Sinn des Lebens beschäftigt die Philosophie seit Jahrtausenden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Grundgesetz ___, dass alle Menschen gleich sind.","options":["besagt","sagt","behauptet","erklärt"],"correctAnswer":"besagt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The study states that coffee can be healthy","wordBankItems":["Die","Studie","besagt",",","dass","Kaffee","gesund","sein","kann","."],"correctAnswer":"Die Studie besagt , dass Kaffee gesund sein kann ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Ethik'' means?","options":["ethics","morality","values","principles"],"correctAnswer":"ethics"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss religion and worldviews","Use konfessionell vocabulary","Talk about religious diversity"],"explanation":{"intro":"Religion vocabulary at B1 allows discussing Germany''s religious landscape and diverse worldviews respectfully.","culturalNote":"Germany has around 55 million Christians (mostly Catholic and Protestant), plus significant Muslim, Jewish, and non-religious populations. Kirchensteuer (church tax) is collected by the state for registered members. The Protestant Reformation began in Germany — Martin Luther posted his 95 theses in Wittenberg in 1517."},"examples":[{"german":"Deutschland ist offiziell kein konfessioneller Staat, aber die Kirchen haben großen Einfluss.","english":"Germany is officially not a confessional state, but the churches have great influence."},{"german":"Religionsfreiheit ist im Grundgesetz verankert.","english":"Freedom of religion is enshrined in the Basic Law."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss religion and worldviews respectfully in German."}}',
'{"items":[{"word":"konfessionell","translation":"confessional/denominational","pronunciation":"kon-fes-see-oh-NEL","example":"Konfessioneller Staat."},{"word":"verankert","translation":"enshrined/anchored","pronunciation":"fer-AN-kert","example":"Im Gesetz verankert."},{"word":"die Religionsfreiheit","translation":"freedom of religion","pronunciation":"dee reh-lee-GYOHNS-fry-hyt","example":"Religionsfreiheit."},{"word":"gläubig","translation":"devout/religious","pronunciation":"GLOW-bikh","example":"Gläubige Menschen."},{"word":"die Konfession","translation":"denomination","pronunciation":"dee kon-fes-SYOHN","example":"Welche Konfession?"},{"word":"weltanschaulich","translation":"relating to worldview","pronunciation":"VELT-an-show-likh","example":"Weltanschauliche Fragen."}]}',
'{"title":"Verankert sein in — to be enshrined/anchored in","pattern":"etwas ist in [law/document] verankert (to be enshrined in)","explanation":"Verankert in (anchored in, enshrined in) — passive adjective from verankern (to anchor). Das Recht ist im Grundgesetz verankert = The right is enshrined in the Basic Law. Die Werte sind in der Gesellschaft verankert = The values are anchored in society. Very common in legal and political language.","examples":[{"sentence":"Das Recht auf freie Meinungsäußerung ist im Grundgesetz verankert.","translation":"The right to free expression is enshrined in the Basic Law."},{"sentence":"Diese Traditionen sind tief in der Kultur verankert.","translation":"These traditions are deeply rooted in the culture."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gläubig'' means?","options":["devout/religious","believing","faithful","spiritual"],"correctAnswer":"devout/religious"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Freedom of religion is enshrined in the Basic Law.","options":["Religionsfreiheit ist im Grundgesetz verankert.","Das Grundgesetz schützt Religion.","In Deutschland ist Religion frei.","Die Kirche ist im Grundgesetz."],"correctAnswer":"Religionsfreiheit ist im Grundgesetz verankert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Recht auf freie Meinungsäußerung ist im Grundgesetz ___.","options":["verankert","verankert worden","verankern","zu verankern"],"correctAnswer":"verankert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: These traditions are deeply rooted in the culture","wordBankItems":["Diese","Traditionen","sind","tief","in","der","Kultur","verankert","."],"correctAnswer":"Diese Traditionen sind tief in der Kultur verankert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Konfession'' means?","options":["denomination","confession","religion","faith"],"correctAnswer":"denomination"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social justice","Use Gleichstellung vocabulary","Talk about inequality and fairness"],"explanation":{"intro":"Social justice vocabulary at B1 covers equality, fairness, and discrimination — increasingly important topics.","culturalNote":"Germany has legal frameworks for gender equality (Gleichstellung) and anti-discrimination (Antidiskriminierungsgesetz). The pay gap (Gender Pay Gap) and women in leadership (Frauen in Führungspositionen) are ongoing debates. The General Equal Treatment Act (AGG) protects against discrimination."},"examples":[{"german":"Das Ziel der Gleichstellung ist es, alle Menschen fair zu behandeln.","english":"The goal of equality is to treat all people fairly."},{"german":"Diskriminierung aufgrund der Herkunft ist gesetzlich verboten.","english":"Discrimination on grounds of origin is prohibited by law."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss social justice and equality topics in German."}}',
'{"items":[{"word":"die Gleichstellung","translation":"equality/equal treatment","pronunciation":"dee GLYKH-shtel-oong","example":"Geschlechtergleichstellung."},{"word":"aufgrund + genitive","translation":"on grounds of/due to","pronunciation":"OWF-groond","example":"Aufgrund der Herkunft."},{"word":"gesetzlich verboten","translation":"prohibited by law","pronunciation":"geh-ZETS-likh fer-BOH-ten","example":"Gesetzlich verboten."},{"word":"die Benachteiligung","translation":"disadvantage/discrimination","pronunciation":"dee beh-NAKH-ty-lee-goong","example":"Benachteiligung verhindern."},{"word":"fair behandeln","translation":"to treat fairly","pronunciation":"fayr beh-HAN-deln","example":"Alle fair behandeln."},{"word":"die Chancengleichheit","translation":"equal opportunity","pronunciation":"dee KHAN-tsen-glykh-hyt","example":"Chancengleichheit fördern."}]}',
'{"title":"Aufgrund + genitive — due to/on grounds of","pattern":"aufgrund + genitive noun (due to, on grounds of, on account of)","explanation":"Aufgrund + genitive: Aufgrund der Herkunft = on grounds of origin. Aufgrund seiner Leistungen = because of his achievements. In formal and legal language. Masculine genitive: des/eines + -(e)s. Feminine: der/einer. Plural: der. Alternative: wegen + genitive (less formal). Aufgrund is preferred in legal/official texts.","examples":[{"sentence":"Aufgrund des schlechten Wetters mussten wir absagen.","translation":"Due to the bad weather we had to cancel."},{"sentence":"Aufgrund ihrer Qualifikationen bekam sie die Stelle.","translation":"Due to her qualifications she got the position."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Chancengleichheit'' means?","options":["equal opportunity","equality","fair chance","equal rights"],"correctAnswer":"equal opportunity"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Discrimination on grounds of origin is prohibited by law.","options":["Diskriminierung aufgrund der Herkunft ist gesetzlich verboten.","Diskriminierung ist verboten.","Herkunft darf nicht diskriminiert werden.","Das Gesetz schützt vor Diskriminierung."],"correctAnswer":"Diskriminierung aufgrund der Herkunft ist gesetzlich verboten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Aufgrund ___ Qualifikationen bekam sie die Stelle.","options":["ihrer","ihre","ihr","ihren"],"correctAnswer":"ihrer"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Due to the bad weather we had to cancel","wordBankItems":["Aufgrund","des","schlechten","Wetters","mussten","wir","absagen","."],"correctAnswer":"Aufgrund des schlechten Wetters mussten wir absagen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Gleichstellung'' means?","options":["equality/equal treatment","equal rights","fairness","non-discrimination"],"correctAnswer":"equality/equal treatment"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss human rights","Use Menschenwürde vocabulary","Talk about rights and responsibilities"],"explanation":{"intro":"Human rights vocabulary at B1 allows discussing fundamental rights and their importance.","culturalNote":"The German Basic Law begins with ''Die Würde des Menschen ist unantastbar'' (Human dignity is inviolable). This reflects lessons learned from the Nazi era. Germany actively supports international human rights through the Auswärtiges Amt (Federal Foreign Office) and NGOs."},"examples":[{"german":"Die Würde des Menschen ist unantastbar — das ist der erste Satz des Grundgesetzes.","english":"Human dignity is inviolable — that is the first sentence of the Basic Law."},{"german":"Jeder Mensch hat das Recht auf ein faires Verfahren.","english":"Every person has the right to a fair trial."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss human rights and fundamental freedoms in German."}}',
'{"items":[{"word":"die Würde","translation":"dignity","pronunciation":"dee VÜR-deh","example":"Menschenwürde."},{"word":"unantastbar","translation":"inviolable/untouchable","pronunciation":"OON-an-tast-bar","example":"Unantastbar sein."},{"word":"das Recht auf","translation":"the right to","pronunciation":"dahs REKHT owf","example":"Das Recht auf Bildung."},{"word":"das faire Verfahren","translation":"fair trial","pronunciation":"dahs FAY-reh fer-FAH-ren","example":"Ein faires Verfahren."},{"word":"die Grundrechte","translation":"fundamental rights","pronunciation":"dee GROOND-rekh-teh","example":"Die Grundrechte."},{"word":"verletzten","translation":"to violate/injure","pronunciation":"fer-LETS-ten","example":"Rechte verletzen."}]}',
'{"title":"Das Recht auf + accusative — the right to","pattern":"das Recht auf + accusative noun / das Recht, zu + infinitive","explanation":"Das Recht auf + accusative: das Recht auf Bildung (the right to education), das Recht auf Arbeit (the right to work). Alternatively: das Recht zu + infinitive: das Recht, frei zu wählen (the right to vote freely). Both structures work. Violation: ein Recht verletzen (violate a right). Guarantee: ein Recht gewährleisten (guarantee a right).","examples":[{"sentence":"Alle Menschen haben das Recht auf Meinungsfreiheit.","translation":"All people have the right to freedom of opinion."},{"sentence":"Das Recht auf Privatsphäre muss geschützt werden.","translation":"The right to privacy must be protected."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unantastbar'' means?","options":["inviolable/untouchable","immovable","unchangeable","absolute"],"correctAnswer":"inviolable/untouchable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Human dignity is inviolable — that is the first sentence of the Basic Law.","options":["Die Würde des Menschen ist unantastbar — das ist der erste Satz des Grundgesetzes.","Die Würde ist wichtig für das Grundgesetz.","Das Grundgesetz schützt die Würde.","Unantastbar ist die Menschenwürde."],"correctAnswer":"Die Würde des Menschen ist unantastbar — das ist der erste Satz des Grundgesetzes."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Alle Menschen haben das Recht auf ___.","options":["Meinungsfreiheit","der Meinungsfreiheit","die Meinungsfreiheit","Meinungsfreiheiten"],"correctAnswer":"Meinungsfreiheit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The right to privacy must be protected","wordBankItems":["Das","Recht","auf","Privatsphäre","muss","geschützt","werden","."],"correctAnswer":"Das Recht auf Privatsphäre muss geschützt werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Grundrechte'' means?","options":["fundamental rights","basic rights","civil rights","human rights"],"correctAnswer":"fundamental rights"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss globalisation","Use Vernetzung vocabulary","Talk about global trade and culture"],"explanation":{"intro":"Globalisation vocabulary at B1 covers interconnectedness, trade, and cultural exchange.","culturalNote":"Germany is one of the world''s largest exporters and deeply integrated into global supply chains. The term Globalisierung is widely used but contested — debates about winners and losers of globalisation are common in German media."},"examples":[{"german":"Die Globalisierung hat die Welt stärker miteinander vernetzt.","english":"Globalisation has connected the world more closely together."},{"german":"Freihandelsabkommen erleichtern den internationalen Handel.","english":"Free trade agreements facilitate international trade."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss globalisation and its impacts in German."}}',
'{"items":[{"word":"vernetzen","translation":"to connect/network","pronunciation":"fer-NET-sen","example":"Länder vernetzen."},{"word":"das Freihandelsabkommen","translation":"free trade agreement","pronunciation":"dahs FRY-han-dels-ap-kom-en","example":"Ein Freihandelsabkommen."},{"word":"erleichtern","translation":"to facilitate/ease","pronunciation":"er-LYK-tern","example":"Den Handel erleichtern."},{"word":"die Lieferkette","translation":"supply chain","pronunciation":"dee LEE-fer-ket-eh","example":"Die Lieferkette."},{"word":"der Weltmarkt","translation":"world market","pronunciation":"dayr VELT-markt","example":"Auf dem Weltmarkt."},{"word":"grenzüberschreitend","translation":"cross-border","pronunciation":"GRENTS-ü-ber-shry-tend","example":"Grenzüberschreitend tätig."}]}',
'{"title":"Miteinander — together/with each other","pattern":"miteinander + verb (to do something together/with each other)","explanation":"Miteinander (together, with each other) combines mit + einander. Die Länder handeln miteinander = The countries trade with each other. Miteinander reden = to talk to each other. Compare: zusammen (together — in the same space/time), miteinander (reciprocal action). Füreinander = for each other. Voneinander = from each other.","examples":[{"sentence":"Die Kulturen bereichern sich gegenseitig miteinander.","translation":"The cultures enrich each other mutually."},{"sentence":"Wir müssen miteinander kooperieren.","translation":"We need to cooperate with each other."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Lieferkette'' means?","options":["supply chain","delivery chain","logistical chain","value chain"],"correctAnswer":"supply chain"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Globalisation has connected the world more closely together.","options":["Die Globalisierung hat die Welt stärker miteinander vernetzt.","Globalisierung vernetzt die Welt.","Die Welt ist vernetzt.","Globalisierung verbindet Menschen."],"correctAnswer":"Die Globalisierung hat die Welt stärker miteinander vernetzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir müssen ___ kooperieren.","options":["miteinander","zusammen","füreinander","voneinander"],"correctAnswer":"miteinander"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Free trade agreements facilitate international trade","wordBankItems":["Freihandelsabkommen","erleichtern","den","internationalen","Handel","."],"correctAnswer":"Freihandelsabkommen erleichtern den internationalen Handel ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erleichtern'' means?","options":["to facilitate/ease","to lighten","to simplify","to reduce"],"correctAnswer":"to facilitate/ease"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss migration and integration","Use Einwanderung vocabulary","Talk about integration policies"],"explanation":{"intro":"Migration and integration vocabulary is highly relevant in contemporary Germany.","culturalNote":"Germany took in over a million refugees in 2015 (Flüchtlingskrise). The Integration (integration) debate is ongoing. Einbürgerung (naturalisation) requires B1 German. The concept of Willkommenskultur (welcoming culture) versus Abschiebung (deportation) reflects ongoing tensions."},"examples":[{"german":"Deutschland ist ein Einwanderungsland, auch wenn das lange bestritten wurde.","english":"Germany is a country of immigration, even if that was long denied."},{"german":"Eine erfolgreiche Integration setzt Sprachkenntnisse und gesellschaftliche Teilhabe voraus.","english":"Successful integration requires language skills and social participation."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss migration and integration policies in German."}}',
'{"items":[{"word":"das Einwanderungsland","translation":"country of immigration","pronunciation":"dahs YN-van-der-oongs-land","example":"Ein Einwanderungsland."},{"word":"bestreiten","translation":"to deny/dispute","pronunciation":"beh-SHTRYT-en","example":"Etwas bestreiten."},{"word":"die Teilhabe","translation":"participation","pronunciation":"dee TYL-hah-beh","example":"Gesellschaftliche Teilhabe."},{"word":"voraussetzen","translation":"to require/presuppose","pronunciation":"for-OWS-zet-sen","example":"Kenntnisse voraussetzen."},{"word":"die Einbürgerung","translation":"naturalisation","pronunciation":"dee YN-bür-ger-oong","example":"Die Einbürgerung beantragen."},{"word":"die Abschiebung","translation":"deportation","pronunciation":"dee AP-shee-boong","example":"Eine Abschiebung."}]}',
'{"title":"Voraussetzen — to require/presuppose","pattern":"etwas setzt etwas voraus (something requires/presupposes something)","explanation":"Voraussetzen (separable) = to require, presuppose. Integration setzt Sprachkenntnisse voraus = Integration requires language skills. Passive: Sprachkenntnisse werden vorausgesetzt = Language skills are required. Common in job postings: Berufserfahrung wird vorausgesetzt = Professional experience is required. Die Voraussetzung (requirement/condition): eine Voraussetzung erfüllen (to meet a requirement).","examples":[{"sentence":"Das Studium setzt ein bestandenes Abitur voraus.","translation":"University study requires a passed Abitur."},{"sentence":"Für diese Stelle werden Englischkenntnisse vorausgesetzt.","translation":"English skills are required for this position."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Teilhabe'' means?","options":["participation","inclusion","involvement","belonging"],"correctAnswer":"participation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany is a country of immigration, even if that was long denied.","options":["Deutschland ist ein Einwanderungsland, auch wenn das lange bestritten wurde.","Deutschland nimmt Einwanderer auf.","Viele Menschen kommen nach Deutschland.","Deutschland war immer ein Einwanderungsland."],"correctAnswer":"Deutschland ist ein Einwanderungsland, auch wenn das lange bestritten wurde."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Studium setzt ein bestandenes Abitur ___.","options":["voraus","vor","voraus haben","vorausgesetzt"],"correctAnswer":"voraus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: English skills are required for this position","wordBankItems":["Für","diese","Stelle","werden","Englischkenntnisse","vorausgesetzt","."],"correctAnswer":"Für diese Stelle werden Englischkenntnisse vorausgesetzt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Einbürgerung'' means?","options":["naturalisation","citizenship","residency","registration"],"correctAnswer":"naturalisation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss volunteering in German","Use Ehrenamt vocabulary","Talk about civic engagement"],"explanation":{"intro":"Volunteering vocabulary covers civic engagement, which is a major part of German civil society.","culturalNote":"Germany has a strong Ehrenamt (honorary/voluntary work) culture. About 28 million Germans volunteer. Feuerwehr (fire brigade), THW (Technical Relief Organisation), DRK (Red Cross) — many rely on volunteers. The Deutsche Ehrenamtsstiftung promotes volunteering."},"examples":[{"german":"Ich engagiere mich ehrenamtlich bei der Feuerwehr.","english":"I volunteer with the fire brigade."},{"german":"Das Ehrenamt ist das Rückgrat der deutschen Zivilgesellschaft.","english":"Volunteering is the backbone of German civil society."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss volunteering and civic engagement in German."}}',
'{"items":[{"word":"sich engagieren","translation":"to get involved/engage","pronunciation":"zikh en-gah-ZHEER-en","example":"Sich engagieren."},{"word":"ehrenamtlich","translation":"voluntary/honorary","pronunciation":"EY-ren-amt-likh","example":"Ehrenamtlich helfen."},{"word":"das Rückgrat","translation":"backbone/spine","pronunciation":"dahs RÜK-graht","example":"Das Rückgrat der Gesellschaft."},{"word":"die Feuerwehr","translation":"fire brigade","pronunciation":"dee FOY-er-vayr","example":"Bei der Feuerwehr."},{"word":"der Verein","translation":"club/association","pronunciation":"dayr fer-YN","example":"Einem Verein beitreten."},{"word":"die Zivilcourage","translation":"civil courage","pronunciation":"dee tsee-vil-koo-RAH-zheh","example":"Zivilcourage zeigen."}]}',
'{"title":"Sich engagieren — to get involved/engage","pattern":"sich engagieren (in/bei + dative) for a cause or organisation","explanation":"Sich engagieren (to engage, get involved, be active). Sich engagieren bei + dative organisation: Ich engagiere mich beim DRK = I am active with the Red Cross. Sich engagieren für + accusative cause: sich für Umweltschutz engagieren = to be active for environmental protection. Ehrenamtlich (adverb) = on a voluntary basis. Das Ehrenamt (noun) = voluntary/honorary office.","examples":[{"sentence":"Sie engagiert sich seit Jahren für Kinderrechte.","translation":"She has been engaged in children''s rights for years."},{"sentence":"Er engagiert sich ehrenamtlich als Trainer.","translation":"He volunteers as a coach."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Zivilcourage'' means?","options":["civil courage","bravery","civic spirit","public courage"],"correctAnswer":"civil courage"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I volunteer with the fire brigade.","options":["Ich engagiere mich ehrenamtlich bei der Feuerwehr.","Ich helfe bei der Feuerwehr.","Ich arbeite ehrenamtlich.","Bei der Feuerwehr bin ich aktiv."],"correctAnswer":"Ich engagiere mich ehrenamtlich bei der Feuerwehr."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie engagiert sich seit Jahren ___ Kinderrechte.","options":["für","bei","zu","in"],"correctAnswer":"für"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He volunteers as a coach","wordBankItems":["Er","engagiert","sich","ehrenamtlich","als","Trainer","."],"correctAnswer":"Er engagiert sich ehrenamtlich als Trainer ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Rückgrat'' when used figuratively means?","options":["backbone","foundation","support","core"],"correctAnswer":"backbone"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss civil society","Use Bürgergesellschaft vocabulary","Talk about NGOs and civic organisations"],"explanation":{"intro":"Civil society vocabulary covers non-governmental organisations, citizen movements, and participatory democracy.","culturalNote":"German civil society (Zivilgesellschaft) is robust. Bürgerinitiativen (citizen initiatives) have shaped policy — the anti-nuclear movement, peace movement, and environmental groups all started from civil society. Bürgerbegehren (citizen''s petition) allows direct democracy at local level."},"examples":[{"german":"Bürgerinitiativen können den politischen Diskurs maßgeblich beeinflussen.","english":"Citizen initiatives can significantly influence the political discourse."},{"german":"Die Zivilgesellschaft kontrolliert die staatliche Macht.","english":"Civil society controls state power."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss civil society and citizen participation in German."}}',
'{"items":[{"word":"die Bürgerinitiative","translation":"citizen initiative","pronunciation":"dee BÜR-ger-in-ee-tsya-tee-veh","example":"Eine Bürgerinitiative."},{"word":"maßgeblich","translation":"significantly/decisively","pronunciation":"MAHS-gayp-likh","example":"Maßgeblich beeinflussen."},{"word":"der Diskurs","translation":"discourse","pronunciation":"dayr dis-KOORS","example":"Politischer Diskurs."},{"word":"kontrolliern","translation":"to monitor/control","pronunciation":"kon-tro-LEER-en","example":"Die Macht kontrollieren."},{"word":"staatlich","translation":"state/governmental","pronunciation":"SHTAHT-likh","example":"Staatliche Macht."},{"word":"partizipieren","translation":"to participate","pronunciation":"par-tee-tsee-PEER-en","example":"Aktiv partizipieren."}]}',
'{"title":"Maßgeblich — significantly/decisively (adverb)","pattern":"maßgeblich + beeinflussen/prägen/beitragen (to significantly influence/shape/contribute)","explanation":"Maßgeblich = significantly, decisively, substantially (from Maß = measure/standard). Maßgeblich beeinflussen = to significantly influence. Maßgeblich beitragen = to make a significant contribution. Maßgeblich beteiligt sein = to be significantly involved. It implies the contribution or influence was decisive, not minor. Formal register — common in academic and journalistic German.","examples":[{"sentence":"Er hat maßgeblich zur Entwicklung des Projekts beigetragen.","translation":"He made a significant contribution to the project''s development."},{"sentence":"Die neue Technologie hat maßgeblich die Branche verändert.","translation":"The new technology has significantly changed the industry."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Staatlich'' means?","options":["state/governmental","public","official","national"],"correctAnswer":"state/governmental"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Citizen initiatives can significantly influence the political discourse.","options":["Bürgerinitiativen können den politischen Diskurs maßgeblich beeinflussen.","Bürger beeinflussen die Politik.","Der Diskurs wird von Bürgern beeinflusst.","Bürgerinitiativen sind wichtig."],"correctAnswer":"Bürgerinitiativen können den politischen Diskurs maßgeblich beeinflussen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er hat ___ zur Entwicklung des Projekts beigetragen.","options":["maßgeblich","grundlegend","wesentlich","erheblich"],"correctAnswer":"maßgeblich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The new technology has significantly changed the industry","wordBankItems":["Die","neue","Technologie","hat","maßgeblich","die","Branche","verändert","."],"correctAnswer":"Die neue Technologie hat maßgeblich die Branche verändert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Partizipieren'' means?","options":["to participate","to partake","to join","to engage"],"correctAnswer":"to participate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss housing in Germany at B1","Use Mietrecht vocabulary","Talk about tenant rights"],"explanation":{"intro":"Housing vocabulary at B1 covers tenancy, rights, and the rental market — crucial for life in Germany.","culturalNote":"Germany has one of Europe''s highest renting rates. Most Germans rent rather than own — just 45% own their home (EU average ~70%). Tenant rights (Mieterrechte) are strong. The Mieterverein (tenants'' association) is powerful. Nebenkosten (utility costs) are typically separate from rent."},"examples":[{"german":"Als Mieter hat man das Recht auf eine ordentliche Übergabe der Wohnung.","english":"As a tenant one has the right to a proper handover of the flat."},{"german":"Die Nebenkostenabrechnung muss dem Mieter bis Ende des Folgejahres zugehen.","english":"The utilities bill must reach the tenant by the end of the following year."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss tenant rights and housing law in German."}}',
'{"items":[{"word":"die Übergabe","translation":"handover","pronunciation":"dee ü-ber-GAH-beh","example":"Übergabe der Wohnung."},{"word":"die Nebenkosten","translation":"utility costs","pronunciation":"dee NAY-ben-kos-ten","example":"Nebenkosten zahlen."},{"word":"die Nebenkostenabrechnung","translation":"utilities bill","pronunciation":"dee NAY-ben-kos-ten-ap-rekh-noong","example":"Nebenkostenabrechnung."},{"word":"kündigen","translation":"to give notice/cancel","pronunciation":"KÜN-dee-gen","example":"Den Mietvertrag kündigen."},{"word":"die Kaution","translation":"deposit","pronunciation":"dee kow-TSYOHN","example":"Kaution zahlen."},{"word":"der Mieterverein","translation":"tenants'' association","pronunciation":"dayr MEE-ter-fer-yn","example":"Mieterverein beitreten."}]}',
'{"title":"Zugehen — to reach someone (formal)","pattern":"etwas geht jemandem zu (something reaches/is sent to someone)","explanation":"Zugehen (separable, intransitive) = to reach, be delivered to. Formal legal/administrative use. Die Kündigung geht Ihnen zu = The notice will be sent to you. Mir ist das Schreiben zugegangen = The letter has reached me. Very common in tenancy law: Die Nebenkostenabrechnung muss dem Mieter zugehen = The bill must reach the tenant. Active: zustellen (to deliver formally).","examples":[{"sentence":"Das Kündigungsschreiben muss dem Vermieter rechtzeitig zugehen.","translation":"The notice of termination must reach the landlord in good time."},{"sentence":"Ihnen wird die Bestätigung per E-Mail zugehen.","translation":"You will receive the confirmation by email."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Kaution'' means?","options":["deposit","security","payment","guarantee"],"correctAnswer":"deposit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"As a tenant one has the right to a proper handover of the flat.","options":["Als Mieter hat man das Recht auf eine ordentliche Übergabe der Wohnung.","Mieter haben Rechte.","Eine Wohnungsübergabe ist Pflicht.","Als Mieter muss man eine Übergabe machen."],"correctAnswer":"Als Mieter hat man das Recht auf eine ordentliche Übergabe der Wohnung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Kündigungsschreiben muss dem Vermieter rechtzeitig ___.","options":["zugehen","zugegangen","zukommen","zustellen"],"correctAnswer":"zugehen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: You will receive the confirmation by email","wordBankItems":["Ihnen","wird","die","Bestätigung","per","E-Mail","zugehen","."],"correctAnswer":"Ihnen wird die Bestätigung per E-Mail zugehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kündigen'' in rental context means?","options":["to give notice/cancel","to resign","to fire","to terminate"],"correctAnswer":"to give notice/cancel"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000fa',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss consumption and advertising","Use Werbung vocabulary","Critically analyse advertising"],"explanation":{"intro":"Consumer and advertising vocabulary at B1 covers marketing language and consumer culture.","culturalNote":"Germany has strict advertising regulations — comparative advertising (Vergleichswerbung), tobacco ads near schools, alcohol ads targeting minors, and misleading claims are regulated. Stiftung Warentest (a German consumer organisation) is highly trusted for product testing."},"examples":[{"german":"Werbung beeinflusst unser Kaufverhalten oft unbewusst.","english":"Advertising often influences our purchasing behaviour unconsciously."},{"german":"Stiftung Warentest testet Produkte unabhängig und ohne Werbefinanzierung.","english":"Stiftung Warentest tests products independently and without advertising funding."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss consumption, advertising, and consumer protection in German."}}',
'{"items":[{"word":"das Kaufverhalten","translation":"purchasing behaviour","pronunciation":"dahs KOWF-fer-hal-ten","example":"Das Kaufverhalten."},{"word":"unbewusst","translation":"unconsciously/unaware","pronunciation":"OON-beh-voost","example":"Unbewusst reagieren."},{"word":"unabhängig","translation":"independent","pronunciation":"OON-ap-heng-ikh","example":"Unabhängig testen."},{"word":"die Werbefinanzierung","translation":"advertising funding","pronunciation":"dee VER-beh-fee-nan-tseer-oong","example":"Ohne Werbefinanzierung."},{"word":"verleiten zu","translation":"to entice/tempt into","pronunciation":"fer-LY-ten tsoo","example":"Zum Kauf verleiten."},{"word":"der Verbraucherschutz","translation":"consumer protection","pronunciation":"dayr fer-BROW-kher-shoots","example":"Verbraucherschutz."}]}',
'{"title":"Verleiten zu — to entice/lead astray into","pattern":"jemanden verleiten zu + dative noun or infinitive (to entice someone into)","explanation":"Verleiten zu (to entice, lead astray): Werbung verleitet zum Kauf = Advertising entices into buying (zum = zu + dem). Verleiten has a negative connotation — being led into something you shouldn''t. Negative variant: jemanden dazu verleiten, etwas zu tun (to lead someone to do something). Compare neutral: motivieren (to motivate), animieren (to encourage).","examples":[{"sentence":"Soziale Medien verleiten uns dazu, unser Leben zu vergleichen.","translation":"Social media leads us to compare our lives."},{"sentence":"Rabatte sollen zum Impulskauf verleiten.","translation":"Discounts are meant to entice impulse purchases."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Verbraucherschutz'' means?","options":["consumer protection","consumer rights","buyer protection","market regulation"],"correctAnswer":"consumer protection"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Advertising often influences our purchasing behaviour unconsciously.","options":["Werbung beeinflusst unser Kaufverhalten oft unbewusst.","Werbung verändert uns.","Kaufverhalten ist unbewusst.","Wir kaufen wegen Werbung."],"correctAnswer":"Werbung beeinflusst unser Kaufverhalten oft unbewusst."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Rabatte sollen zum Impulskauf ___.","options":["verleiten","anregen","animieren","motivieren"],"correctAnswer":"verleiten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Social media leads us to compare our lives","wordBankItems":["Soziale","Medien","verleiten","uns","dazu",",","unser","Leben","zu","vergleichen","."],"correctAnswer":"Soziale Medien verleiten uns dazu , unser Leben zu vergleichen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unbewusst'' means?","options":["unconsciously","unknowingly","unintentionally","involuntarily"],"correctAnswer":"unconsciously"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000fb',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss fashion and design","Use Stil vocabulary","Talk about aesthetics and trends"],"explanation":{"intro":"Fashion and design vocabulary at B1 covers style, aesthetics, and the fashion industry.","culturalNote":"Germany has a significant fashion industry, especially in Berlin, Munich, and Düsseldorf. Bread & Butter (now part of Berlin Fashion Week) is a key trade show. German design philosophy (Bauhaus, functional design) values Funktionalität über Dekoration."},"examples":[{"german":"Das Bauhaus-Prinzip ''Form folgt Funktion'' beeinflusst noch immer das Design.","english":"The Bauhaus principle ''form follows function'' still influences design."},{"german":"Der aktuelle Modetrend setzt auf nachhaltige Materialien.","english":"The current fashion trend relies on sustainable materials."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss fashion, design principles, and aesthetics in German."}}',
'{"items":[{"word":"die Ästhetik","translation":"aesthetics","pronunciation":"dee ess-TAY-tik","example":"Visuelle Ästhetik."},{"word":"das Prinzip","translation":"principle","pronunciation":"dahs prin-TSIP","example":"Ein Design-Prinzip."},{"word":"setzen auf","translation":"to rely on/bet on","pronunciation":"ZET-sen owf","example":"Auf Qualität setzen."},{"word":"nachhaltig","translation":"sustainable","pronunciation":"NAKH-hal-tikh","example":"Nachhaltige Mode."},{"word":"der Entwurf","translation":"design/draft/sketch","pronunciation":"dayr ENT-voorf","example":"Einen Entwurf vorlegen."},{"word":"der Zeitgeist","translation":"spirit of the times","pronunciation":"dayr TSYT-gyst","example":"Den Zeitgeist widerspiegeln."}]}',
'{"title":"Setzen auf — to rely on/place emphasis on","pattern":"auf etwas setzen + accusative (to bet on/rely on/place emphasis on)","explanation":"Setzen auf + accusative: to bet on, rely on, put emphasis on. Der Trend setzt auf Nachhaltigkeit = The trend bets on sustainability. Wir setzen auf Qualität = We rely on quality. Can be figurative (make a strategic bet) or literal (a horse bet). Note: to set (table) = den Tisch decken. Context distinguishes gambling meaning from strategic/design meaning.","examples":[{"sentence":"Das Unternehmen setzt auf innovative Technologien.","translation":"The company bets on innovative technologies."},{"sentence":"Die Designerin setzt auf natürliche Farben.","translation":"The designer relies on natural colours."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Zeitgeist'' means?","options":["spirit of the times","time spirit","trend","current mood"],"correctAnswer":"spirit of the times"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The current fashion trend relies on sustainable materials.","options":["Der aktuelle Modetrend setzt auf nachhaltige Materialien.","Mode wird nachhaltiger.","Nachhaltige Mode ist im Trend.","Der Trend ist nachhaltig."],"correctAnswer":"Der aktuelle Modetrend setzt auf nachhaltige Materialien."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Designerin setzt auf natürliche ___.","options":["Farben","Farbe","Farbwahl","Farbige"],"correctAnswer":"Farben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The company bets on innovative technologies","wordBankItems":["Das","Unternehmen","setzt","auf","innovative","Technologien","."],"correctAnswer":"Das Unternehmen setzt auf innovative Technologien ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Entwurf'' means?","options":["design/draft/sketch","project","plan","concept"],"correctAnswer":"design/draft/sketch"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000fc',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German food culture","Use gastronomy vocabulary","Talk about regional cuisines"],"explanation":{"intro":"Gastronomy vocabulary at B1 covers restaurants, culinary traditions, and food culture.","culturalNote":"German cuisine has enormous regional variety — Bayerisch (Bavarian), Schwäbisch (Swabian), Rheinisch (Rhineland), Norddeutsch (North German). Brot (bread) is culturally central — Germany has over 3000 types of bread. The Michelin star scene is vibrant. Gemütlichkeit (cosiness/conviviality) in restaurants is valued."},"examples":[{"german":"Die deutsche Küche ist regional sehr verschieden — Bayern isst anders als der Norden.","english":"German cuisine varies greatly by region — Bavaria eats differently than the north."},{"german":"Das Restaurant hat drei Michelin-Sterne und eine monatelange Warteliste.","english":"The restaurant has three Michelin stars and a months-long waiting list."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss gastronomy, food culture, and regional German cuisines."}}',
'{"items":[{"word":"regional","translation":"regional","pronunciation":"reh-gee-oh-NAHL","example":"Regionale Küche."},{"word":"die Küche","translation":"cuisine/kitchen","pronunciation":"dee KÜ-kheh","example":"Die deutsche Küche."},{"word":"die Warteliste","translation":"waiting list","pronunciation":"dee VAR-teh-lis-teh","example":"Auf der Warteliste."},{"word":"die Spezialität","translation":"speciality","pronunciation":"dee speh-tsee-ah-lee-TÄT","example":"Eine regionale Spezialität."},{"word":"hausgemacht","translation":"home-made","pronunciation":"HOWS-geh-makht","example":"Hausgemachte Nudeln."},{"word":"die Gemütlichkeit","translation":"cosiness/conviviality","pronunciation":"dee geh-MÜT-likh-kyt","example":"Deutsche Gemütlichkeit."}]}',
'{"title":"Schmecken — to taste (impersonal + dative)","pattern":"Das schmeckt mir (gut/nicht) — it tastes good/bad to me (dative)","explanation":"Schmecken (to taste, to taste good): Das schmeckt mir = I like the taste of that / That tastes good to me. Dative person. Das schmeckt mir nicht = I don''t like the taste. Wie schmeckt es dir? = How does it taste to you? Past: Das hat mir geschmeckt = I enjoyed that. Note: es schmeckt (tastes good) vs. es riecht (smells). Impersonal with dative (like gefallen, passen).","examples":[{"sentence":"Das bayerische Bier schmeckt mir besonders gut.","translation":"I particularly like the taste of Bavarian beer."},{"sentence":"Wie hat Ihnen das Essen geschmeckt?","translation":"How did you enjoy the meal?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Gemütlichkeit'' means?","options":["cosiness/conviviality","warmth","comfort","friendliness"],"correctAnswer":"cosiness/conviviality"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"German cuisine varies greatly by region — Bavaria eats differently than the north.","options":["Die deutsche Küche ist regional sehr verschieden — Bayern isst anders als der Norden.","Deutschland hat gutes Essen.","Bayern und der Norden essen verschieden.","Regionale Unterschiede gibt es."],"correctAnswer":"Die deutsche Küche ist regional sehr verschieden — Bayern isst anders als der Norden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das bayerische Bier schmeckt ___ besonders gut.","options":["mir","mich","mein","mich sehr"],"correctAnswer":"mir"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: How did you enjoy the meal?","wordBankItems":["Wie","hat","Ihnen","das","Essen","geschmeckt","?"],"correctAnswer":"Wie hat Ihnen das Essen geschmeckt ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Hausgemacht'' means?","options":["home-made","house specialty","traditional","artisan"],"correctAnswer":"home-made"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000fd',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss agriculture and food production","Use Landwirtschaft vocabulary","Talk about organic farming"],"explanation":{"intro":"Agriculture vocabulary at B1 covers farming, food production, and sustainability.","culturalNote":"Germany has significant agricultural land (47% of territory). The debate between konventionelle Landwirtschaft (conventional) and ökologische Landwirtschaft (organic/ecological) is intense. Bio-Siegel (organic seal) is ubiquitous. Discounters like Aldi and Lidl increasingly stock Bio products."},"examples":[{"german":"Ökologische Landwirtschaft verzichtet auf synthetische Pestizide.","english":"Organic farming does without synthetic pesticides."},{"german":"Der Strukturwandel in der Landwirtschaft führt zu immer größeren Betrieben.","english":"Structural change in agriculture is leading to ever larger farms."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss agriculture, farming, and food production in German."}}',
'{"items":[{"word":"ökologisch","translation":"organic/ecological","pronunciation":"ö-koh-LOH-gish","example":"Ökologische Landwirtschaft."},{"word":"verzichten auf","translation":"to do without/forego","pronunciation":"fer-TSIKH-ten owf","example":"Auf Pestizide verzichten."},{"word":"synthetisch","translation":"synthetic","pronunciation":"zün-TAY-tish","example":"Synthetische Mittel."},{"word":"der Strukturwandel","translation":"structural change","pronunciation":"dayr SHTROOK-toor-van-del","example":"Strukturwandel erfassen."},{"word":"der Betrieb","translation":"farm/operation/business","pronunciation":"dayr beh-TREEP","example":"Ein großer Betrieb."},{"word":"die Ernte","translation":"harvest","pronunciation":"dee ERN-teh","example":"Die Ernte einfahren."}]}',
'{"title":"Verzichten auf — to do without/forego","pattern":"auf etwas verzichten + accusative (to do without, renounce, forego)","explanation":"Verzichten auf + accusative = to do without, give up, abstain from. Auf Zucker verzichten = to do without sugar. Auf ein Recht verzichten = to waive a right. Past: hat auf...verzichtet. Note: no negative connotation (unlike sich enthalten = to abstain). Can be positive choice: Ich verzichte bewusst auf Fleisch = I consciously do without meat. Die Verzichtserklärung = waiver statement.","examples":[{"sentence":"Er hat auf sein Erbe verzichtet.","translation":"He renounced his inheritance."},{"sentence":"Sie verzichtet auf Alkohol aus gesundheitlichen Gründen.","translation":"She does without alcohol for health reasons."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Ernte'' means?","options":["harvest","yield","crop","gathering"],"correctAnswer":"harvest"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Organic farming does without synthetic pesticides.","options":["Ökologische Landwirtschaft verzichtet auf synthetische Pestizide.","Bio-Landwirtschaft ist natürlich.","Keine Pestizide im Bio-Anbau.","Ökologisch bedeutet ohne Chemie."],"correctAnswer":"Ökologische Landwirtschaft verzichtet auf synthetische Pestizide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie verzichtet auf Alkohol aus gesundheitlichen ___.","options":["Gründen","Gründe","dem Grund","Grund"],"correctAnswer":"Gründen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He renounced his inheritance","wordBankItems":["Er","hat","auf","sein","Erbe","verzichtet","."],"correctAnswer":"Er hat auf sein Erbe verzichtet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Strukturwandel'' means?","options":["structural change","economic shift","transformation","reorganisation"],"correctAnswer":"structural change"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000fe',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss energy and resources","Use Energiewende vocabulary","Talk about renewable vs fossil energy"],"explanation":{"intro":"Energy vocabulary at B1 covers Germany''s energy transition and global resource challenges.","culturalNote":"Germany''s Energiewende (energy transition) is a policy to shift from nuclear and fossil fuels to renewables. By 2022, Germany had closed all nuclear plants. The debate about coal (Kohle), gas (Gas), and renewables is central to German politics. Windkraft (wind energy) and Solarenergie are major contributors."},"examples":[{"german":"Deutschland hat bis 2022 alle Atomkraftwerke abgeschaltet.","english":"Germany switched off all nuclear power plants by 2022."},{"german":"Der Ausbau erneuerbarer Energien ist ein zentrales Ziel der Klimapolitik.","english":"Expanding renewable energies is a central goal of climate policy."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss energy policy, the Energiewende, and resources in German."}}',
'{"items":[{"word":"das Atomkraftwerk","translation":"nuclear power plant","pronunciation":"dahs AH-tom-kraft-verk","example":"Atomkraftwerke abschalten."},{"word":"abschalten","translation":"to switch off/shut down","pronunciation":"AP-shal-ten","example":"Reaktor abschalten."},{"word":"der Ausbau","translation":"expansion/development","pronunciation":"dayr OWS-bow","example":"Der Ausbau von Windkraft."},{"word":"fossile Brennstoffe","translation":"fossil fuels","pronunciation":"fos-SEE-leh BREN-shtof-eh","example":"Fossile Brennstoffe ersetzen."},{"word":"die Windkraft","translation":"wind energy","pronunciation":"dee VINT-kraft","example":"Windkraft ausbauen."},{"word":"der Strommix","translation":"energy mix","pronunciation":"dayr SHTROM-miks","example":"Der deutsche Strommix."}]}',
'{"title":"Abschalten — to switch off/shut down","pattern":"etwas abschalten (separable) — to switch off, shut down","explanation":"Abschalten (separable) = to switch off (machine, plant), shut down. Deutschland hat die AKWs abgeschaltet = Germany shut down the nuclear plants. Also colloquial: abschalten = to unwind/switch off (mentally). Ich muss mal abschalten = I need to switch off / unwind. The dual meaning (technical shutdown + mental relaxation) is worth knowing.","examples":[{"sentence":"Am Wochenende kann ich gut abschalten.","translation":"I can unwind well at the weekend."},{"sentence":"Das letzte Atomkraftwerk wurde 2023 abgeschaltet.","translation":"The last nuclear power plant was shut down in 2023."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Strommix'' means?","options":["energy mix","electricity mix","power mix","grid mix"],"correctAnswer":"energy mix"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany switched off all nuclear power plants by 2022.","options":["Deutschland hat bis 2022 alle Atomkraftwerke abgeschaltet.","Deutschland hat keine Atomkraft mehr.","2022 wurde das Letzte abgeschaltet.","Alle AKWs sind zu."],"correctAnswer":"Deutschland hat bis 2022 alle Atomkraftwerke abgeschaltet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Am Wochenende kann ich gut ___.","options":["abschalten","ausschalten","entspannen","schalten"],"correctAnswer":"abschalten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Expanding renewable energies is a central goal of climate policy","wordBankItems":["Der","Ausbau","erneuerbarer","Energien","ist","ein","zentrales","Ziel","der","Klimapolitik","."],"correctAnswer":"Der Ausbau erneuerbarer Energien ist ein zentrales Ziel der Klimapolitik ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Colloquially, ''abschalten'' also means?","options":["to unwind/relax mentally","to turn off","to disconnect","to stop"],"correctAnswer":"to unwind/relax mentally"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000ff',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss space and science","Use Raumfahrt vocabulary","Talk about scientific discoveries"],"explanation":{"intro":"Space and science vocabulary at B1 covers key scientific fields and space exploration.","culturalNote":"Germany has significant space involvement through ESA (European Space Agency) and DLR (Deutsches Zentrum für Luft- und Raumfahrt). Wernher von Braun (rocket scientist) and Albert Einstein are famous German scientists. The Max-Planck-Gesellschaft and Fraunhofer-Gesellschaft are world-leading research institutions."},"examples":[{"german":"Die Raumstation ISS ist ein internationales Gemeinschaftsprojekt.","english":"The ISS space station is an international cooperative project."},{"german":"Wissenschaftliche Entdeckungen verändern oft unser Weltbild grundlegend.","english":"Scientific discoveries often fundamentally change our worldview."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss space exploration and scientific discoveries in German."}}',
'{"items":[{"word":"die Raumstation","translation":"space station","pronunciation":"dee ROWM-shta-tsyohn","example":"Die Raumstation ISS."},{"word":"das Gemeinschaftsprojekt","translation":"cooperative project","pronunciation":"dahs geh-MYN-shafts-proh-yekt","example":"Ein Gemeinschaftsprojekt."},{"word":"die Entdeckung","translation":"discovery","pronunciation":"dee ent-DEK-oong","example":"Eine Entdeckung machen."},{"word":"das Weltbild","translation":"worldview/world picture","pronunciation":"dahs VELT-bilt","example":"Das Weltbild verändern."},{"word":"forschen","translation":"to research/do research","pronunciation":"FOR-shen","example":"Aktiv forschen."},{"word":"das Experiment","translation":"experiment","pronunciation":"dahs eks-peh-ree-MENT","example":"Ein Experiment durchführen."}]}',
'{"title":"Durchführen — to carry out/conduct","pattern":"etwas durchführen (separable) — to carry out, conduct, implement","explanation":"Durchführen (separable) = to carry out, conduct (an experiment, project, survey). Ein Experiment durchführen = to conduct an experiment. Eine Studie durchführen = to carry out a study. Passive: Das Experiment wurde durchgeführt = The experiment was carried out. Related: die Durchführung = implementation/conduct. Durchführbar = feasible, practicable.","examples":[{"sentence":"Die Studie wurde von Forschern der Universität durchgeführt.","translation":"The study was carried out by researchers from the university."},{"sentence":"Das Experiment ist schwer durchzuführen.","translation":"The experiment is difficult to carry out."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Weltbild'' means?","options":["worldview/world picture","world image","global view","universe"],"correctAnswer":"worldview/world picture"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The ISS space station is an international cooperative project.","options":["Die Raumstation ISS ist ein internationales Gemeinschaftsprojekt.","Die ISS ist international.","Viele Länder bauten die ISS.","ISS ist ein Raumfahrtprojekt."],"correctAnswer":"Die Raumstation ISS ist ein internationales Gemeinschaftsprojekt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Studie wurde von Forschern der Universität ___.","options":["durchgeführt","durchführen","durchführt","durchzuführen"],"correctAnswer":"durchgeführt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The experiment is difficult to carry out","wordBankItems":["Das","Experiment","ist","schwer","durchzuführen","."],"correctAnswer":"Das Experiment ist schwer durchzuführen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Gemeinschaftsprojekt'' means?","options":["cooperative project","community project","joint venture","partnership project"],"correctAnswer":"cooperative project"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000100',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss psychological concepts","Use Psychologie vocabulary","Talk about behaviour and cognition"],"explanation":{"intro":"Psychology vocabulary at B1 allows discussing human behaviour, cognition, and mental processes.","culturalNote":"Sigmund Freud (Austrian but German-speaking) and Carl Jung are foundational figures. Germany has a strong tradition of clinical psychology (klinische Psychologie). Cognitive behavioural therapy (kognitive Verhaltenstherapie) is widely used. Burnout and Stress are common diagnoses in Germany."},"examples":[{"german":"Das Unterbewusstsein beeinflusst unser Verhalten oft ohne unser Wissen.","english":"The subconscious influences our behaviour often without our knowledge."},{"german":"Kognitive Verhaltenstherapie hilft, negative Denkmuster zu erkennen.","english":"Cognitive behavioural therapy helps to recognise negative thought patterns."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss psychological concepts and human behaviour in German."}}',
'{"items":[{"word":"das Unterbewusstsein","translation":"subconscious","pronunciation":"dahs OON-ter-beh-voost-zyn","example":"Das Unterbewusstsein."},{"word":"das Denkmuster","translation":"thought pattern","pronunciation":"dahs DENK-moos-ter","example":"Negative Denkmuster."},{"word":"das Verhalten","translation":"behaviour","pronunciation":"dahs fer-HAL-ten","example":"Das Verhalten ändern."},{"word":"erkennen","translation":"to recognise/identify","pronunciation":"er-KEN-en","example":"Ein Muster erkennen."},{"word":"die kognitive Verhaltenstherapie","translation":"cognitive behavioural therapy","pronunciation":"dee kog-nee-TEE-veh fer-HAL-tens-teh-rah-PEE","example":"KVT anwenden."},{"word":"unbewusst","translation":"unconscious/subconscious","pronunciation":"OON-beh-voost","example":"Unbewusste Reaktion."}]}',
'{"title":"Helfen + infinitive clause — helps to do something","pattern":"etwas/jemand hilft, [zu + infinitive] (to help to do something)","explanation":"Helfen (to help) + zu + infinitive: Das hilft, die Situation zu verstehen = That helps to understand the situation. With person: Jemanden helfen, etwas zu tun = help someone to do something: Die Therapie hilft ihm, Muster zu erkennen = The therapy helps him to recognise patterns. Note: helfen takes dative person: mir helfen, dir helfen. Dative + zu-infinitive structure.","examples":[{"sentence":"Regelmäßige Bewegung hilft, Stress abzubauen.","translation":"Regular exercise helps to reduce stress."},{"sentence":"Die Therapie hilft ihr, mit ihren Gefühlen umzugehen.","translation":"The therapy helps her to deal with her feelings."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Denkmuster'' means?","options":["thought pattern","thinking style","mental model","cognitive pattern"],"correctAnswer":"thought pattern"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The subconscious influences our behaviour often without our knowledge.","options":["Das Unterbewusstsein beeinflusst unser Verhalten oft ohne unser Wissen.","Wir handeln unbewusst.","Das Unterbewusstsein ist wichtig.","Verhalten ist unbewusst."],"correctAnswer":"Das Unterbewusstsein beeinflusst unser Verhalten oft ohne unser Wissen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Regelmäßige Bewegung hilft, Stress ___.","options":["abzubauen","zu abbauen","abbauen","abgebaut"],"correctAnswer":"abzubauen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The therapy helps her to deal with her feelings","wordBankItems":["Die","Therapie","hilft","ihr",",","mit","ihren","Gefühlen","umzugehen","."],"correctAnswer":"Die Therapie hilft ihr , mit ihren Gefühlen umzugehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Helfen takes which case for the person being helped?","options":["dative","accusative","nominative","genitive"],"correctAnswer":"dative"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000101',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss sociological concepts","Use Gesellschaft vocabulary","Talk about social structures"],"explanation":{"intro":"Sociology vocabulary at B1 introduces social structures, norms, and concepts for discussing society.","culturalNote":"German sociological tradition is rich — Max Weber (Rationalisierung), Georg Simmel, Theodor Adorno, Jürgen Habermas are major figures. The concept of Sozialstaat (welfare state) is central to German identity. Social equality (soziale Gerechtigkeit) is a core political value."},"examples":[{"german":"Soziale Normen definieren, was in einer Gesellschaft als akzeptabel gilt.","english":"Social norms define what is considered acceptable in a society."},{"german":"Der demografische Wandel stellt die Sozialsysteme vor große Herausforderungen.","english":"Demographic change is posing great challenges to social systems."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss sociological concepts and social structures in German."}}',
'{"items":[{"word":"die Norm","translation":"norm/standard","pronunciation":"dee NORM","example":"Soziale Normen."},{"word":"der demografische Wandel","translation":"demographic change","pronunciation":"dayr de-moh-GRAH-fish-eh VAN-del","example":"Demografischer Wandel."},{"word":"das Sozialsystem","translation":"social system","pronunciation":"dahs ZO-tsyal-süs-tem","example":"Das Sozialsystem."},{"word":"die Herausforderung","translation":"challenge","pronunciation":"dee her-OWS-for-der-oong","example":"Eine Herausforderung."},{"word":"definieren","translation":"to define","pronunciation":"deh-fee-NEER-en","example":"Begriffe definieren."},{"word":"die Schicht","translation":"social class/layer","pronunciation":"dee SHIKHT","example":"Soziale Schicht."}]}',
'{"title":"Vor Herausforderungen stehen — to face challenges","pattern":"etwas steht vor Herausforderungen / jemanden stellt vor Herausforderungen","explanation":"Jdn/etw vor Herausforderungen stellen = to pose challenges to someone/something. Der Wandel stellt die Systeme vor Herausforderungen = Change poses challenges to the systems. Also: Vor Herausforderungen stehen = to be facing challenges. Das System steht vor großen Herausforderungen = The system is facing major challenges. Both structures are very common in formal German.","examples":[{"sentence":"Die Digitalisierung stellt Unternehmen vor neue Herausforderungen.","translation":"Digitalisation poses new challenges to companies."},{"sentence":"Wir stehen vor der Herausforderung, die Kosten zu senken.","translation":"We are facing the challenge of reducing costs."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Schicht'' in social context means?","options":["social class/layer","shift","layer","stratum"],"correctAnswer":"social class/layer"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Demographic change is posing great challenges to social systems.","options":["Der demografische Wandel stellt die Sozialsysteme vor große Herausforderungen.","Die Demografie verändert sich.","Sozialsysteme haben Probleme.","Der Wandel ist eine Herausforderung."],"correctAnswer":"Der demografische Wandel stellt die Sozialsysteme vor große Herausforderungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Digitalisierung stellt Unternehmen vor neue ___.","options":["Herausforderungen","Herausforderung","Aufgaben","Probleme"],"correctAnswer":"Herausforderungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We are facing the challenge of reducing costs","wordBankItems":["Wir","stehen","vor","der","Herausforderung",",","die","Kosten","zu","senken","."],"correctAnswer":"Wir stehen vor der Herausforderung , die Kosten zu senken ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Definieren'' means?","options":["to define","to determine","to describe","to explain"],"correctAnswer":"to define"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000102',1,'APPROVED','PUBLISHED',
'{"objectives":["Understand the German legal system","Use Recht vocabulary","Discuss rights and legal proceedings"],"explanation":{"intro":"Legal vocabulary at B1 covers the basics of the German legal system.","culturalNote":"Germany has a civil law system (Zivilrecht) based on the Bürgerliches Gesetzbuch (BGB — Civil Code, 1900). There are five court levels: Amtsgericht (magistrate), Landgericht (regional), Oberlandesgericht (higher regional), Bundesgerichtshof (federal supreme court). Legal aid (Prozesskostenhilfe) is available for those who cannot afford legal fees."},"examples":[{"german":"Das Bürgerliche Gesetzbuch regelt die privaten Rechtsbeziehungen in Deutschland.","english":"The Civil Code governs private legal relationships in Germany."},{"german":"Jeder Angeklagte hat das Recht auf einen Anwalt.","english":"Every defendant has the right to a lawyer."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss the German legal system and basic legal rights in German."}}',
'{"items":[{"word":"das Bürgerliche Gesetzbuch","translation":"Civil Code (BGB)","pronunciation":"dahs BÜR-ger-likh-eh geh-ZETS-bookh","example":"Das BGB regelt."},{"word":"regeln","translation":"to regulate/govern","pronunciation":"REY-geln","example":"Gesetze regeln."},{"word":"der Angeklagte","translation":"defendant/accused","pronunciation":"dayr AN-geh-klah-gteh","example":"Der Angeklagte."},{"word":"die Klage","translation":"lawsuit/complaint","pronunciation":"dee KLAH-geh","example":"Eine Klage einreichen."},{"word":"das Urteil","translation":"verdict/judgement","pronunciation":"dahs OOR-tyl","example":"Ein Urteil sprechen."},{"word":"die Berufung","translation":"appeal","pronunciation":"dee beh-ROO-foong","example":"Berufung einlegen."}]}',
'{"title":"Einreichen — to file/submit (formal)","pattern":"etwas einreichen (separable) — to file, submit formally (documents, applications, complaints)","explanation":"Einreichen (separable) = to file, submit formally. Eine Klage einreichen = to file a lawsuit. Einen Antrag einreichen = to submit an application. Very formal — used only for official submissions to authorities or courts. Past: hat eingereicht. Die Einreichung = the submission. Note: abgeben is the general submit (hand in homework), einreichen implies formal/official context.","examples":[{"sentence":"Sie hat Klage gegen den Arbeitgeber eingereicht.","translation":"She filed a complaint against the employer."},{"sentence":"Der Antrag muss bis Freitag eingereicht werden.","translation":"The application must be submitted by Friday."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Urteil'' means?","options":["verdict/judgement","ruling","decision","sentence"],"correctAnswer":"verdict/judgement"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Every defendant has the right to a lawyer.","options":["Jeder Angeklagte hat das Recht auf einen Anwalt.","Angeklagte brauchen Anwälte.","Recht auf Anwalt ist wichtig.","Ein Anwalt ist gesetzlich nötig."],"correctAnswer":"Jeder Angeklagte hat das Recht auf einen Anwalt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Antrag muss bis Freitag ___ werden.","options":["eingereicht","einreichen","eingereicht sein","zu reichen"],"correctAnswer":"eingereicht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She filed a complaint against the employer","wordBankItems":["Sie","hat","Klage","gegen","den","Arbeitgeber","eingereicht","."],"correctAnswer":"Sie hat Klage gegen den Arbeitgeber eingereicht ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Berufung'' in legal context means?","options":["appeal","vocation","calling","appointment"],"correctAnswer":"appeal"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000103',1,'APPROVED','PUBLISHED',
'{"objectives":["Deepen cultural knowledge of Germany","Discuss regional differences","Use Landeskunde vocabulary"],"explanation":{"intro":"Deutschlandkunde (German studies/cultural knowledge) covers geography, regional identities, and cultural features.","culturalNote":"Germany is a federal republic of 16 Bundesländer. North-South differences are significant: Bavaria (Gemütlichkeit, tradition) vs. Berlin (cosmopolitan, alternative). Hamburg (Hanseatic, mercantile), Rhine area (wine, Karneval). Germany was divided until 1990 and some East-West differences persist in culture and economy."},"examples":[{"german":"Bayern pflegt sehr stark seine regionalen Traditionen und Trachten.","english":"Bavaria maintains its regional traditions and traditional dress very strongly."},{"german":"Die Unterschiede zwischen Ost und West sind nach der Wende geringer geworden.","english":"The differences between East and West have become smaller since reunification."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German regional cultures and national characteristics."}}',
'{"items":[{"word":"pflegen","translation":"to maintain/cherish/cultivate","pronunciation":"PFLAY-gen","example":"Traditionen pflegen."},{"word":"die Tracht","translation":"traditional costume","pronunciation":"dee TRAKHT","example":"Die bayerische Tracht."},{"word":"die Wende","translation":"the turn (1989 reunification)","pronunciation":"dee VEN-deh","example":"Seit der Wende."},{"word":"geringer","translation":"smaller/less","pronunciation":"geh-RING-er","example":"Geringer werden."},{"word":"die Vielfalt","translation":"diversity/variety","pronunciation":"dee FEEL-falt","example":"Kulturelle Vielfalt."},{"word":"das Bundesland","translation":"federal state","pronunciation":"dahs BOON-des-land","example":"Das Bundesland Bayern."}]}',
'{"title":"Pflegen — to maintain/cultivate (traditions)","pattern":"etwas pflegen (to maintain, cultivate, care for — traditions, relationships, health)","explanation":"Pflegen = to care for, maintain, cultivate. Traditionen pflegen = to maintain traditions. Kontakte pflegen = to maintain contacts. Pflege (noun) = care. Altenpflege (elderly care), Gesundheitspflege (health care), Denkmalpflege (monument preservation). Very versatile — the core meaning is careful ongoing maintenance of something valued.","examples":[{"sentence":"Er pflegt engen Kontakt zu seiner Familie.","translation":"He maintains close contact with his family."},{"sentence":"Diese Region pflegt ihre alten Handwerkstraditionen.","translation":"This region maintains its old craft traditions."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Wende'' in German context refers to?","options":["the 1989-90 turn/reunification period","a turning point","change","transition"],"correctAnswer":"the 1989-90 turn/reunification period"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Bavaria maintains its regional traditions and traditional dress very strongly.","options":["Bayern pflegt sehr stark seine regionalen Traditionen und Trachten.","Bayern hat viele Traditionen.","Die Tracht ist typisch bayrisch.","Bayern ist traditionell."],"correctAnswer":"Bayern pflegt sehr stark seine regionalen Traditionen und Trachten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er pflegt engen Kontakt zu seiner ___.","options":["Familie","Familien","der Familie","Familienkreis"],"correctAnswer":"Familie"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This region maintains its old craft traditions","wordBankItems":["Diese","Region","pflegt","ihre","alten","Handwerkstraditionen","."],"correctAnswer":"Diese Region pflegt ihre alten Handwerkstraditionen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Vielfalt'' means?","options":["diversity/variety","richness","abundance","breadth"],"correctAnswer":"diversity/variety"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000104',1,'APPROVED','PUBLISHED',
'{"objectives":["Review B1 progress so far","Celebrate reaching B1 midpoint","Preview B1 second half"],"explanation":{"intro":"You have reached the B1 midpoint — lesson 260! You''ve completed A1, A2, and are halfway through B1. You can now discuss complex topics, understand authentic texts, and handle most everyday situations.","culturalNote":"B1 is the threshold level (Schwellenniveau) in the CEFR. At B1 you can deal with most situations while travelling in German-speaking areas, describe experiences and events, give reasons and explanations, and understand the main points of standard German."},"examples":[{"german":"Ich habe 260 Stunden Deutsch gelernt — das entspricht dem Niveau B1 Mitte.","english":"I have studied 260 hours of German — that corresponds to the B1 midpoint level."},{"german":"Auf zu den nächsten 140 B1-Lektionen!","english":"On to the next 140 B1 lessons!"}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":20,"canDo":"I am at the B1 midpoint — I can discuss complex topics in German!"}}',
'{"items":[{"word":"entsprechen","translation":"to correspond to/match","pronunciation":"ent-SHPREH-khen","example":"Das entspricht B1."},{"word":"das Schwellenniveau","translation":"threshold level","pronunciation":"dahs SHVEL-en-nee-voh","example":"Das Schwellenniveau B1."},{"word":"authentisch","translation":"authentic","pronunciation":"ow-TEN-tish","example":"Authentische Texte."},{"word":"handhaben","translation":"to handle/manage","pronunciation":"HAN-hah-ben","example":"Situationen handhaben."},{"word":"Fortschritte machen","translation":"to make progress","pronunciation":"FORT-shrit-eh MAKH-en","example":"Gute Fortschritte."},{"word":"weiterkommen","translation":"to make progress/advance","pronunciation":"VY-ter-kom-en","example":"Im Deutschen weiterkommen."}]}',
'{"title":"Entsprechen — to correspond to/meet (requirements)","pattern":"etwas/jemand entspricht + dative (something/someone corresponds to/meets)","explanation":"Entsprechen + dative = to correspond to, match, meet. Das entspricht meinen Erwartungen = That meets my expectations. Dative after entsprechen. Very useful: Die Lösung entspricht den Anforderungen = The solution meets the requirements. Die Beschreibung entspricht der Realität = The description corresponds to reality. Past: hat entsprochen.","examples":[{"sentence":"Das Hotel hat nicht unseren Erwartungen entsprochen.","translation":"The hotel did not meet our expectations."},{"sentence":"Die Qualität entspricht dem Preis.","translation":"The quality corresponds to the price."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Schwellenniveau'' in CEFR terms is?","options":["threshold level (B1)","elementary (A2)","basic (A1)","independent user (B2)"],"correctAnswer":"threshold level (B1)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have studied 260 hours of German — that corresponds to the B1 midpoint level.","options":["Ich habe 260 Stunden Deutsch gelernt — das entspricht dem Niveau B1 Mitte.","Ich lerne seit 260 Stunden.","260 Lektionen sind viel.","Ich bin auf B1 Niveau."],"correctAnswer":"Ich habe 260 Stunden Deutsch gelernt — das entspricht dem Niveau B1 Mitte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Hotel hat nicht unseren Erwartungen ___.","options":["entsprochen","entsprechen","entspricht","entsprechend"],"correctAnswer":"entsprochen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The quality corresponds to the price","wordBankItems":["Die","Qualität","entspricht","dem","Preis","."],"correctAnswer":"Die Qualität entspricht dem Preis ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Entsprechen'' takes which case?","options":["dative","accusative","nominative","genitive"],"correctAnswer":"dative"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

